INSERT INTO abilities
    (id, name, ko_name, description, effect)
VALUES
    (1, 'stench', '악취', '악취를 풍겨서 공격했을 때 상대가 풀죽을 때가 있다.', 'Has a 10% chance of making target Pokémon flinch with each hit.'),
    (2, 'drizzle', '잔비', '등장했을 때 날씨를 비로 만든다.', 'Summons rain that lasts indefinitely upon entering battle.'),
    (3, 'speed-boost', '가속', '매 턴 스피드가 올라간다.', 'Raises Speed one stage after each turn.'),
    (4, 'battle-armor', '전투무장', '단단한 껍질에 보호받아 상대의 공격이 급소에 맞지 않는다.', 'Protects against critical hits.'),
    (5, 'sturdy', '옹골참', '상대 기술을 받아도 일격으로 쓰러지지 않는다. 일격필살 기술도 효과 없다.', 'Prevents being KOed from full HP, leaving 1 HP instead.  Protects against the one-hit KO moves regardless of HP.'),
    (6, 'damp', '습기', '주변을 습하게 함으로써 자폭 등 폭발하는 기술을 아무도 못 쓰게 한다.', 'Prevents Self-Destruct, Explosion, and Aftermath from working while the Pokémon is in battle.'),
    (7, 'limber', '유연', '유연한 몸으로 인해 마비 상태가 되지 않는다.', 'Prevents paralysis.'),
    (8, 'sand-veil', '모래숨기', '모래바람일 때 회피율이 올라간다.', 'Increases evasion to 1.25× during a sandstorm.  Protects against sandstorm damage.'),
    (9, 'static', '정전기', '정전기를 몸에 둘러 접촉한 상대를 마비시킬 때가 있다.', 'Has a 30% chance of paralyzing attacking Pokémon on contact.'),
    (10, 'volt-absorb', '축전', '전기타입의 기술을 받으면 데미지를 받지 않고 회복한다.', 'Absorbs Electric moves, healing for 1/4 max HP.'),
    (11, 'water-absorb', '저수', '물타입의 기술을 받으면 데미지를 받지 않고 회복한다.', 'Absorbs Water moves, healing for 1/4 max HP.'),
    (12, 'oblivious', '둔감', '둔감해서 헤롱헤롱이나 도발 상태가 되지 않는다.', 'Prevents infatuation and protects against Captivate.'),
    (13, 'cloud-nine', '날씨부정', '모든 날씨의 영향이 없어진다.', 'Negates all effects of weather, but does not prevent the weather itself.'),
    (14, 'compound-eyes', '복안', '복안을 가지고 있어 기술의 명중률이 올라간다.', 'Increases moves'' accuracy to 1.3×.'),
    (15, 'insomnia', '불면', '잠들지 못하는 체질이라 잠듦 상태가 되지 않는다.', 'Prevents sleep.'),
    (17, 'immunity', '면역', '체내에 면역을 가지고 있어 독 상태가 되지 않는다.', 'Prevents poison.'),
    (18, 'flash-fire', '타오르는불꽃', '불꽃타입의 기술을 받으면 불꽃을 받아서 자신이 사용하는 불꽃타입의 기술이 강해진다.', 'Protects against Fire moves.  Once one has been blocked, the Pokémon''s own Fire moves inflict 1.5× damage until it leaves battle.'),
    (19, 'shield-dust', '인분', '인분에 보호받아 기술의 추가 효과를 받지 않게 된다.', 'Protects against incoming moves'' extra effects.'),
    (20, 'own-tempo', '마이페이스', '마이페이스라서 혼란 상태가 되지 않는다.', 'Prevents confusion.'),
    (21, 'suction-cups', '흡반', '흡반으로 지면에 달라붙어 포켓몬을 교체시키는 기술이나 도구의 효과를 발휘하지 못하게 한다.', 'Prevents being forced out of battle by other Pokémon''s moves.'),
    (22, 'intimidate', '위협', '등장했을 때 위협해서 상대를 위축시켜 상대의 공격을 떨어뜨린다.', 'Lowers opponents'' Attack one stage upon entering battle.'),
    (23, 'shadow-tag', '그림자밟기', '상대의 그림자를 밟아 도망치거나 교체할 수 없게 한다.', 'Prevents opponents from fleeing or switching out.'),
    (24, 'rough-skin', '까칠한피부', '공격을 받았을 때 자신에게 접촉한 상대를 까칠까칠한 피부로 상처를 입힌다.', 'Damages attacking Pokémon for 1/8 their max HP on contact.'),
    (26, 'levitate', '부유', '땅에서 뜨는 것으로 땅타입의 기술을 받지 않는다.', 'Evades Ground moves.'),
    (27, 'effect-spore', '포자', '공격으로 자신에게 접촉한 상대를 독이나 마비, 잠듦 상태로 만들 때가 있다.', 'Has a 30% chance of inflcting either paralysis, poison, or sleep on attacking Pokémon on contact.'),
    (28, 'synchronize', '싱크로', '자신이 걸린 독이나 마비, 화상을 상대에게 옮긴다.', 'Copies burns, paralysis, and poison received onto the Pokémon that inflicted them.'),
    (29, 'clear-body', '클리어바디', '상대 기술이나 특성으로 능력을 떨어뜨릴 수 없다.', 'Prevents stats from being lowered by other Pokémon.'),
    (30, 'natural-cure', '자연회복', '지닌 포켓몬으로 돌아오면 상태 이상이 회복된다.', 'Cures any major status ailment upon switching out.'),
    (31, 'lightning-rod', '피뢰침', '전기타입의 기술을 자신에게 끌어모아 데미지를 받지 않고 특수공격을 올린다.', 'Redirects single-target Electric moves to this Pokémon where possible.  Absorbs Electric moves, raising Special Attack one stage.'),
    (33, 'swift-swim', '쓱쓱', '비가 오는 날씨일 때 스피드가 올라간다.', 'Doubles Speed during rain.'),
    (34, 'chlorophyll', '엽록소', '날씨가 맑을 때 스피드가 올라간다.', 'Doubles Speed during strong sunlight.'),
    (35, 'illuminate', '발광', '주변을 밝게 하는 것으로 야생 포켓몬과 만나기 쉬워진다.', 'Doubles the wild encounter rate.'),
    (36, 'trace', '트레이스', '등장했을 때 상대의 특성을 트레이스해서 같은 특성이 된다.', 'Copies an opponent''s ability upon entering battle.'),
    (37, 'huge-power', '천하장사', '물리공격의 위력이 2배가 된다.', 'Doubles Attack in battle.'),
    (38, 'poison-point', '독가시', '자신과 접촉한 상대를 독 상태로 만들 때가 있다.', 'Has a 30% chance of poisoning attacking Pokémon on contact.'),
    (39, 'inner-focus', '정신력', '단련한 정신으로 인하여 상대의 공격에 풀죽지 않는다.', 'Prevents flinching.'),
    (40, 'magma-armor', '마그마의무장', '뜨거운 마그마를 몸에 둘러서 얼음 상태가 되지 않는다.', 'Prevents freezing.'),
    (43, 'soundproof', '방음', '소리를 차단하는 것으로 소리 공격을 받지 않는다.', 'Protects against sound-based moves.'),
    (44, 'rain-dish', '젖은접시', '비가 오는 날씨일 때 조금씩 HP를 회복한다.', 'Heals for 1/16 max HP after each turn during rain.'),
    (45, 'sand-stream', '모래날림', '등장했을 때 날씨를 모래바람으로 만든다.', 'Summons a sandstorm that lasts indefinitely upon entering battle.'),
    (46, 'pressure', '프레셔', '프레셔를 줘서 상대가 쓰는 기술의 PP를 많이 줄인다.', 'Increases the PP cost of moves targetting the Pokémon by one.'),
    (47, 'thick-fat', '두꺼운지방', '두꺼운 지방으로 보호되고 있어 불꽃타입과 얼음타입의 기술의 데미지를 반감시킨다.', 'Halves damage from Fire and Ice moves.'),
    (48, 'early-bird', '일찍기상', '잠듦 상태가 되어도 2배 스피드로 깨어날 수 있다.', 'Makes sleep pass twice as quickly.'),
    (49, 'flame-body', '불꽃몸', '자신과 접촉한 상대를 화상 상태로 만들 때가 있다.', 'Has a 30% chance of burning attacking Pokémon on contact.'),
    (51, 'keen-eye', '날카로운눈', '날카로운 눈 덕분에 명중률이 떨어지지 않는다.', 'Prevents accuracy from being lowered.'),
    (52, 'hyper-cutter', '괴력집게', '힘이 자랑인 집게를 가지고 있어 상대가 공격을 떨어뜨리지 못한다.', 'Prevents Attack from being lowered by other Pokémon.'),
    (53, 'pickup', '픽업', '상대가 사용한 도구를 주워올 때가 있다. 모험 중에도 주워온다.', 'Picks up other Pokémon''s used and Flung held items.  May also pick up an item after battle.'),
    (55, 'hustle', '의욕', '자신의 공격이 높아지지만 명중률이 떨어진다.', 'Strengthens physical moves to inflict 1.5× damage, but decreases their accuracy to 0.8×.'),
    (56, 'cute-charm', '헤롱헤롱바디', '자신과 접촉한 상대를 헤롱헤롱 상태로 만들 때가 있다.', 'Has a 30% chance of infatuating attacking Pokémon on contact.'),
    (57, 'plus', '플러스', '플러스나 마이너스의 특성을 가진 포켓몬이 동료에 있으면 자신의 특수공격이 올라간다.', 'Increases Special Attack to 1.5× when a friendly Pokémon has Plus or Minus.'),
    (58, 'minus', '마이너스', '플러스나 마이너스의 특성을 가진 포켓몬이 동료에 있으면 자신의 특수공격이 올라간다.', 'Increases Special Attack to 1.5× when a friendly Pokémon has Plus or Minus.'),
    (59, 'forecast', '기분파', '날씨의 영향을 받아 물타입, 불꽃타입, 얼음타입 중 하나로 변화한다.', 'Changes Castform''s type and form to match the weather.'),
    (60, 'sticky-hold', '점착', '점착질의 몸에 도구가 달라붙어 있어 상대에게 도구를 뺏기지 않는다.', 'Prevents a held item from being removed by other Pokémon.'),
    (61, 'shed-skin', '탈피', '몸의 껍질을 벗어 던져 상태 이상을 회복할 때가 있다.', 'Has a 33% chance of curing any major status ailment after each turn.'),
    (62, 'guts', '근성', '상태 이상이 되면 근성을 보여서 공격이 올라간다.', 'Increases Attack to 1.5× with a major status ailment.'),
    (63, 'marvel-scale', '이상한비늘', '상태 이상이 되면 이상한 비늘이 반응해서 방어가 올라간다.', 'Increases Defense to 1.5× with a major status ailment.'),
    (65, 'overgrow', '심록', 'HP가 줄었을 때 풀타입 기술의 위력이 올라간다.', 'Strengthens Grass moves to inflict 1.5× damage at 1/3 max HP or less.'),
    (66, 'blaze', '맹화', 'HP가 줄었을 때 불꽃타입 기술의 위력이 올라간다.', 'Strengthens Fire moves to inflict 1.5× damage at 1/3 max HP or less.'),
    (67, 'torrent', '급류', 'HP가 줄었을 때 물타입 기술의 위력이 올라간다.', 'Strengthens Water moves to inflict 1.5× damage at 1/3 max HP or less.'),
    (68, 'swarm', '벌레의알림', 'HP가 줄었을 때 벌레타입 기술의 위력이 올라간다.', 'Strengthens Bug moves to inflict 1.5× damage at 1/3 max HP or less.'),
    (69, 'rock-head', '돌머리', '반동을 받는 기술을 사용해도 HP가 줄지 않는다.', 'Protects against recoil damage.'),
    (70, 'drought', '가뭄', '등장했을 때 날씨를 맑음으로 만든다.', 'Summons strong sunlight that lasts indefinitely upon entering battle.'),
    (72, 'vital-spirit', '의기양양', '의기양양해져서 잠듦 상태가 되지 않는다.', 'Prevents sleep.'),
    (73, 'white-smoke', '하얀연기', '하얀 연기의 보호를 받아 상대가 능력을 떨어뜨릴 수 없다.', 'Prevents stats from being lowered by other Pokémon.'),
    (74, 'pure-power', '순수한힘', '요가의 힘으로 물리공격의 위력이 2배가 된다.', 'Doubles Attack in battle.'),
    (75, 'shell-armor', '조가비갑옷', '단단한 껍질의 보호를 받아 상대의 공격이 급소에 맞지 않는다.', 'Protects against critical hits.'),
    (77, 'tangled-feet', '갈지자걸음', '혼란 상태일 때는 회피율이 올라간다.', 'Doubles evasion when confused.'),
    (78, 'motor-drive', '전기엔진', '전기타입의 기술을 받으면 데미지를 받지 않고 스피드가 올라간다.', 'Absorbs Electric moves, raising Speed one stage.'),
    (79, 'rivalry', '투쟁심', '성별이 같으면 투쟁심을 불태워 강해진다. 성별이 다르면 약해진다.', 'Increases damage inflicted to 1.25× against Pokémon of the same gender, but decreases damage to 0.75× against the opposite gender.'),
    (80, 'steadfast', '불굴의마음', '풀죽을 때마다 불굴의 마음을 불태워 스피드가 올라간다.', 'Raises Speed one stage upon flinching.'),
    (81, 'snow-cloak', '눈숨기', '날씨가 싸라기눈일 때 회피율이 올라간다.', 'Increases evasion to 1.25× during hail.  Protects against hail damage.'),
    (82, 'gluttony', '먹보', 'HP가 줄어들면 먹을 나무열매를 HP가 절반일 때 먹어버린다.', 'Makes the Pokémon eat any held Berry triggered by low HP below 1/2 its max HP.'),
    (83, 'anger-point', '분노의경혈', '급소에 공격이 맞으면 크게 분노해 공격력이 최대가 된다.', 'Raises Attack to the maximum of six stages upon receiving a critical hit.'),
    (84, 'unburden', '곡예', '지니던 도구가 없어지면 스피드가 올라간다.', 'Doubles Speed upon using or losing a held item.'),
    (85, 'heatproof', '내열', '내열인 몸으로 인해 불꽃타입 공격의 데미지를 반감한다.', 'Halves damage from Fire moves and burns.'),
    (87, 'dry-skin', '건조피부', '비가 오는 날씨나 물타입의 기술로 HP가 회복되고 맑을 때나 불꽃타입의 기술로는 줄어든다.', 'Causes 1/8 max HP in damage each turn during strong sunlight, but heals for 1/8 max HP during rain.  Increases damage from Fire moves to 1.25×, but absorbs Water moves, healing for 1/4 max HP.'),
    (89, 'iron-fist', '철주먹', '펀치를 사용하는 기술의 위력이 올라간다.', 'Strengthens punch-based moves to 1.2× their power.'),
    (90, 'poison-heal', '포이즌힐', '독 상태가 되면 HP가 줄지 않고 증가한다.', 'Heals for 1/8 max HP after each turn when poisoned in place of damage.'),
    (91, 'adaptability', '적응력', '자신과 같은 타입의 기술 위력이 올라간다.', 'Increases the same-type attack bonus from 1.5× to 2×.'),
    (92, 'skill-link', '스킬링크', '연속 기술을 사용하면 항상 최고 횟수를 사용할 수 있다.', 'Extends two-to-five-hit moves and Triple Kick to their full length every time.'),
    (93, 'hydration', '촉촉바디', '비가 오는 날씨일 때 상태 이상이 회복된다.', 'Cures any major status ailment after each turn during rain.'),
    (94, 'solar-power', '선파워', '날씨가 맑으면 특수공격이 올라가지만 매 턴 HP가 줄어든다.', 'Increases Special Attack to 1.5× but costs 1/8 max HP after each turn during strong sunlight.'),
    (95, 'quick-feet', '속보', '상태 이상이 되면 스피드가 올라간다.', 'Increases Speed to 1.5× with a major status ailment.'),
    (97, 'sniper', '스나이퍼', '공격을 급소에 맞혔을 때 위력이 더욱 올라간다.', 'Strengthens critical hits to inflict 3× damage rather than 2×.'),
    (98, 'magic-guard', '매직가드', '공격 이외에는 데미지를 입지 않는다.', 'Protects against damage not directly caused by a move.'),
    (99, 'no-guard', '노가드', '노가드전법에 따라 서로가 사용하는 기술이 반드시 맞게 된다.', 'Ensures all moves used by and against the Pokémon hit.'),
    (100, 'stall', '시간벌기', '기술을 사용하는 순서가 반드시 마지막이 된다.', 'Makes the Pokémon move last within its move''s priority bracket.'),
    (101, 'technician', '테크니션', '위력이 약한 기술의 위력을 올려서 공격할 수 있다.', 'Strengthens moves of 60 base power or less to 1.5× their power.'),
    (102, 'leaf-guard', '리프가드', '날씨가 맑을 때는 상태 이상이 되지 않는다.', 'Protects against major status ailments during strong sunlight.'),
    (103, 'klutz', '서투름', '지니고 있는 도구를 쓸 수 없다.', 'Prevents the Pokémon from using its held item in battle.'),
    (104, 'mold-breaker', '틀깨기', '상대 특성에 방해받지 않고 상대에게 기술을 쓸 수 있다.', 'Bypasses targets'' abilities if they could hinder or prevent a move.'),
    (105, 'super-luck', '대운', '대운을 가지고 있어 상대의 급소에 공격이 맞기 쉽다.', 'Raises moves'' critical hit rates one stage.'),
    (106, 'aftermath', '유폭', '기절했을 때 접촉한 상대에게 데미지를 준다.', 'Damages the attacker for 1/4 its max HP when knocked out by a contact move.'),
    (107, 'anticipation', '위험예지', '상대가 지닌 위험한 기술을 감지할 수 있다.', 'Notifies all trainers upon entering battle if an opponent has a super-effective move, Self-Destruct, Explosion, or a one-hit KO move.'),
    (108, 'forewarn', '예지몽', '등장했을 때 상대가 지닌 기술을 하나만 꿰뚫어본다.', 'Reveals the opponents'' strongest move upon entering battle.'),
    (109, 'unaware', '천진', '상대의 능력 변화를 무시하고 공격할 수 있다.', 'Ignores other Pokémon''s stat modifiers for damage and accuracy calculation.'),
    (111, 'filter', '필터', '효과가 굉장한 공격의 위력을 약하게 만든다.', 'Decreases damage taken from super-effective moves by 1/4.'),
    (113, 'scrappy', '배짱', '고스트타입 포켓몬에게 노말타입과 격투타입의 기술을 맞게 한다.', 'Lets the Pokémon''s Normal and Fighting moves hit Ghost Pokémon.'),
    (115, 'ice-body', '아이스바디', '날씨가 싸라기눈일 때 HP를 조금씩 회복한다.', 'Heals for 1/16 max HP after each turn during hail.  Protects against hail damage.'),
    (116, 'solid-rock', '하드록', '효과가 굉장한 공격의 위력을 약하게 만든다.', 'Decreases damage taken from super-effective moves by 1/4.'),
