    (148, 'analytic', '애널라이즈', '제일 마지막에 기술을 쓰면 기술의 위력이 올라간다.', 'Strengthens moves to 1.3× their power when moving last.'),
    (149, 'illusion', '일루전', '지닌 포켓몬 중 제일 뒤에 있는 포켓몬으로 둔갑하여 나와서 상대를 속인다.', 'Takes the appearance of the last conscious party Pokémon upon being sent out until hit by a damaging move.'),
    (150, 'imposter', '괴짜', '눈앞의 포켓몬으로 변신해버린다.', 'Transforms upon entering battle.'),
    (151, 'infiltrator', '틈새포착', '상대의 벽이나 대타출동을 뚫고 공격할 수 있다.', 'Bypasses Light Screen, Reflect, and Safeguard.'),
    (152, 'mummy', '미라', '상대가 접촉하면 상대를 미라로 만들어버린다.', 'Changes attacking Pokémon''s abilities to Mummy on contact.'),
    (153, 'moxie', '자기과신', '상대를 쓰러뜨리면 자신감이 붙어서 공격이 올라간다.', 'Raises Attack one stage upon KOing a Pokémon.'),
    (154, 'justified', '정의의마음', '악타입 공격을 받으면 정의감으로 공격이 올라간다.', 'Raises Attack one stage upon taking damage from a Dark move.'),
    (156, 'magic-bounce', '매직미러', '상대가 쓴 변화 기술을 받지 않고 그대로 되받아칠 수 있다.', 'Reflects most non-damaging moves back at their user.'),
    (157, 'sap-sipper', '초식', '풀타입 기술을 받으면 데미지를 입지 않고 공격이 올라간다.', 'Absorbs Grass moves, raising Attack one stage.'),
    (158, 'prankster', '짓궂은마음', '변화 기술을 먼저 쓸 수 있다.', 'Raises non-damaging moves'' priority by one stage.'),
    (159, 'sand-force', '모래의힘', '날씨가 모래바람일 때 바위타입과 땅타입과 강철타입의 위력이 올라간다.', 'Strengthens Rock, Ground, and Steel moves to 1.3× their power during a sandstorm.  Protects against sandstorm damage.'),
    (165, 'aroma-veil', '아로마베일', '자신과 같은 편으로 향하는 멘탈 공격을 막을 수 있다.', 'Protects allies against moves that affect their mental state.'),
    (166, 'flower-veil', '플라워베일', '같은 편의 풀타입 포켓몬은 능력이 떨어지지 않고 상태 이상도 되지 않는다.', 'Protects friendly Grass Pokémon from having their stats lowered by other Pokémon.'),
    (167, 'cheek-pouch', '볼주머니', '어떤 나무열매라도 먹으면 HP도 회복한다.', 'Restores HP upon eating a Berry, in addition to the Berry''s effect.'),
    (168, 'protean', '변환자재', '자신이 사용한 기술과 같은 타입으로 변화한다.', 'Changes the bearer''s type to match each move it uses.'),
    (169, 'fur-coat', '퍼코트', '상대로부터 받는 물리 기술의 데미지가 절반이 된다.', 'Halves damage from physical attacks.'),
    (170, 'magician', '매지션', '기술을 맞은 상대의 도구를 빼앗아 버린다.', 'Steals the target''s held item when the bearer uses a damaging move.'),
    (171, 'bulletproof', '방탄', '상대 구슬이나 폭탄 등 기술을 막을 수 있다.', 'Protects against bullet, ball, and bomb-based moves.'),
    (172, 'competitive', '승기', '능력이 떨어지면 특수공격이 크게 올라간다.', 'Raises Special Attack by two stages upon having any stat lowered.'),
    (173, 'strong-jaw', '옹골찬턱', '턱이 튼튼하여 무는 기술의 위력이 올라간다.', 'Strengthens biting moves to 1.5× their power.'),
    (174, 'refrigerate', '프리즈스킨', '노말타입의 기술이 얼음타입이 된다. 위력이 조금 올라간다.', 'Turns the bearer''s Normal moves into Ice moves and strengthens them to 1.3× their power.'),
    (175, 'sweet-veil', '스위트베일', '같은 편의 포켓몬이 잠들지 않게 된다.', 'Prevents friendly Pokémon from sleeping.'),
